originalCss:
:root{
  --bg:#07111e; --bg-card:#0d1a30; --bg-card2:#10213b; --border:#1f3354;
  --accent:#7c9eff; --accent-soft:rgba(124,158,255,.14);
  --text:#e6edf7; --text-dim:#c7d6ec; --text-faint:#9cb0cf;
  --warn:#f0b24a; --warn-bg:rgba(240,178,74,.10);
  --tip:#5fd3a4; --tip-bg:rgba(95,211,164,.10);
  --sidebar-w:300px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:20px}
body{margin:0;background:var(--bg);color:var(--text);font-family:"Noto Sans JP","Noto Sans CJK JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,sans-serif;font-size:16px;line-height:1.85;overflow-x:hidden}
a{color:var(--accent);text-decoration:none;overflow-wrap:anywhere}
a:hover{text-decoration:underline}
.layout{display:block}
.sidebar{position:fixed;left:0;top:0;width:var(--sidebar-w);height:100vh;overflow-y:auto;background:#050d18;border-right:1px solid var(--border);padding:22px 14px 40px;z-index:50}
.sidebar-title{font-weight:800;font-size:15px;color:#fff;padding:0 8px 14px;border-bottom:1px solid var(--border);margin-bottom:12px}
.sidebar-title span{display:block;font-weight:500;font-size:12px;color:var(--text-faint);margin-top:2px}
.nav-list,.nav-sub{list-style:none;margin:0;padding:0}
.nav-list>li>a{display:block;padding:6px 10px;border-radius:8px;font-size:13.5px;color:var(--text-dim);line-height:1.5;font-weight:500}
.nav-sub{margin:0 0 4px 12px;border-left:1px solid var(--border)}
.nav-sub a{display:block;padding:3px 10px;font-size:12.5px;color:var(--text-faint);line-height:1.5}
.nav-list a:hover{background:var(--accent-soft);text-decoration:none;color:#fff}
.nav-list a.active{background:var(--accent-soft);color:#fff;box-shadow:inset 3px 0 0 var(--accent)}
.main{margin-left:var(--sidebar-w);padding:40px 48px 80px}
.nav-toggle{display:none;position:fixed;top:12px;left:12px;z-index:60;background:var(--accent);color:#07111e;border:0;border-radius:8px;padding:8px 14px;font-weight:700;font-family:inherit;cursor:pointer}

.hero{position:relative;overflow:hidden;border:1px solid var(--border);border-radius:18px;padding:34px 34px 26px;margin-bottom:36px;background:linear-gradient(160deg,#0d1a30,#09142a)}
.hero::before{content:"";position:absolute;top:-120px;right:-80px;width:380px;height:380px;background:radial-gradient(circle,rgba(124,158,255,.28),transparent 70%);pointer-events:none}
.eyebrow{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.04em;color:var(--accent);background:var(--accent-soft);border:1px solid rgba(124,158,255,.35);padding:4px 14px;border-radius:999px}
.hero-title{position:relative;font-size:28px;font-weight:800;color:#fff;margin:16px 0 8px;line-height:1.4}
.hero-sub{position:relative;font-size:15px;color:var(--text-dim);font-weight:700;margin:0 0 10px}
.hero-lead{position:relative;font-size:14.5px;color:var(--text-dim);margin:0 0 18px}
.hero-meta{position:relative;display:flex;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:14px}
.meta-item{padding:2px 22px 2px 0;margin-right:22px;border-right:1px solid var(--border)}
.meta-item:last-child{border-right:0}
.meta-label{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--text-faint)}
.meta-value{display:block;font-size:14.5px;font-weight:700;color:#fff}

.main h2{font-size:23px;font-weight:800;color:#fff;margin:56px 0 18px;padding:12px 0 12px 16px;border-left:4px solid var(--accent);background:linear-gradient(90deg,var(--accent-soft),transparent)}
.main h3{font-size:18.5px;font-weight:700;color:#dbe6ff;margin:34px 0 12px;padding-bottom:6px;border-bottom:1px dashed var(--border)}
.main h4{font-size:16px;color:#cfe0ff;margin:22px 0 8px}
.main p{margin:12px 0;color:var(--text)}
.main ul,.main ol{padding-left:1.5em;margin:10px 0}
.main li{margin:4px 0}
.main strong{color:#fff}
.main hr{border:0;border-top:1px solid var(--border);margin:36px 0}
.main code:not(pre code){background:#13264a;color:#bcd0ff;padding:2px 7px;border-radius:6px;font-size:.88em;font-family:"JetBrains Mono",ui-monospace,Menlo,Consolas,monospace;overflow-wrap:anywhere}

.table-scroll{overflow-x:auto;margin:16px 0;border:1px solid var(--border);border-radius:12px;background:var(--bg-card)}
.table-scroll table{border-collapse:collapse;width:100%;font-size:14.5px}
.table-scroll th{background:#13264a;color:#fff;text-align:left;padding:10px 14px;font-weight:700;white-space:nowrap;border-bottom:1px solid var(--border)}
.table-scroll td{padding:10px 14px;border-top:1px solid var(--border);vertical-align:top;color:var(--text-dim);min-width:90px}
.table-scroll tr:hover td{background:rgba(124,158,255,.05)}

.callout{border-radius:12px;padding:12px 18px 8px;margin:18px 0;border:1px solid var(--border);border-left-width:4px;background:var(--bg-card)}
.callout p{margin:6px 0 10px;color:var(--text-dim)}
.callout-label{font-size:12px;font-weight:800;letter-spacing:.05em;margin-bottom:2px}
.callout-note{border-left-color:var(--accent)} .callout-note .callout-label{color:var(--accent)}
.callout-warn{border-left-color:var(--warn);background:var(--warn-bg)} .callout-warn .callout-label{color:var(--warn)}
.callout-practice{border-left-color:var(--tip);background:var(--tip-bg)} .callout-practice .callout-label{color:var(--tip)}

.code-block{margin:16px 0;border:1px solid var(--border);border-radius:12px;background:#050d18;overflow-x:auto}
.code-block pre{margin:0;padding:16px 18px;font-size:13.5px;line-height:1.65;font-family:"JetBrains Mono",ui-monospace,Menlo,Consolas,monospace;color:#d6e2f8}
.t-tag{color:#7cc4ff}.t-attr{color:#f0b27a}.t-str{color:#9be29b}.t-meta{color:#8a9bb8}

.mermaid-diagram{display:block;overflow-x:auto;margin:20px 0;padding:22px 16px;border:1px solid var(--border);border-radius:14px;background:var(--bg-card)}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;height:auto}
.mermaid-diagram p{color:inherit;margin:0}
.mermaid-diagram .nodeLabel,.mermaid-diagram .edgeLabel{color:#eaf1ff}

.page-footer{margin-top:64px;padding-top:18px;border-top:1px solid var(--border);font-size:12.5px;color:var(--text-faint)}

@media (max-width:900px){
  .sidebar{transform:translateX(-100%);transition:transform .2s}
  .sidebar.open{transform:none}
  .nav-toggle{display:block}
  .main{margin-left:0;padding:64px 18px 60px}
  .hero{padding:24px 18px 18px}
  .hero-title{font-size:23px}
  .meta-item{border-right:0;border-bottom:1px solid var(--border);width:100%;padding:6px 0;margin:0}
  .meta-item:last-child{border-bottom:0}
}
